import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

bool _registered = false;

/// The adapter's MIT license is generated by Flutter. Bundle the upstream
/// glyph licenses too: Lucide ISC and the retained Feather MIT notice.
void registerThirdPartyLicenses() {
  if (_registered) return;
  _registered = true;
  LicenseRegistry.addLicense(() async* {
    final license = await rootBundle.loadString(
      'assets/licenses/lucide-LICENSE',
    );
    yield LicenseEntryWithLineBreaks(['Lucide / Feather icons'], license);
  });
}
